#[derive(Debug)]
struct StartupFailure {
    code: &'static str,
    message: String,
}

impl StartupFailure {
    fn new(code: &'static str, message: impl Into<String>) -> Self {
        Self {
            code,
            message: message.into(),
        }
    }
}

fn main() {
    let args = std::env::args().collect::<Vec<_>>();
    if args.get(1).is_some_and(|arg| arg == "--self-check") {
        let result = if args.len() == 3 {
            desktop_self_check::run_desktop_self_check(Path::new(&args[2]))
        } else {
            Err("Usage: --self-check <new-isolated-directory>".to_string())
        };
        match result {
            Ok(report) => println!("{report}"),
            Err(error) => {
                println!("{}", json!({"ok": false, "error": error}));
                std::process::exit(1);
            }
        }
        return;
    }
    if args.len() == 2 && args[1] == "--version" {
        println!("{WINDOWS_CLIENT_VERSION}");
        return;
    }
    if args.iter().any(|arg| arg == "--test-bell") {
        let kind = test_bell_kind_from_args(&args);
        play_timer_bell_sequence(kind);
        return;
    }
    install_client_panic_log();
    append_client_runtime_log(&format!("START version={WINDOWS_CLIENT_VERSION}"));
    match run_windows_client() {
        Ok(()) => append_client_runtime_log("EXIT clean"),
        Err(failure) => {
            append_client_runtime_log(&format!(
                "EXIT startup_failure code={} message={}",
                failure.code, failure.message
            ));
            show_startup_failure(&failure);
            std::process::exit(1);
        }
    }
}

fn run_windows_client() -> Result<(), StartupFailure> {
    let activation_requested = Arc::new(AtomicBool::new(false));
    #[cfg(target_os = "windows")]
    let app_root = app_dir();
    #[cfg(target_os = "windows")]
    let legacy_root = legacy_app_dir();
    #[cfg(target_os = "windows")]
    let _single_instance_guard = match acquire_windows_client_for_current_release(&app_root) {
        Ok(Some(guard)) => guard,
        Ok(None) => {
            return Ok(());
        }
        Err(error) => {
            return Err(StartupFailure::new(
                "GTW-START-001",
                format!("无法建立本地数据库单实例保护：{error}"),
            ));
        }
    };
    #[cfg(target_os = "windows")]
    let _activation_server =
        WindowsClientActivationServer::start(&app_root, Arc::clone(&activation_requested))
            .map_err(|error| {
                StartupFailure::new("GTW-START-004", format!("无法建立单实例唤醒通道：{error}"))
            })?;
    #[cfg(target_os = "windows")]
    let _legacy_instance_guard = match WindowsClientInstanceGuard::acquire(&legacy_root) {
        Ok(Some(guard)) => guard,
        Ok(None) => {
            return Err(StartupFailure::new(
                "GTW-START-002",
                "检测到旧版计时器仍持有数据目录；请关闭旧客户端后重试。",
            ));
        }
        Err(error) => {
            return Err(StartupFailure::new(
                "GTW-START-003",
                format!("无法建立旧数据目录排他保护：{error}"),
            ));
        }
    };
    append_client_runtime_log("STARTUP_GUARDS_READY");
    let startup_fonts = DesktopStartupFonts::start();
    let options = eframe::NativeOptions {
        viewport: egui::ViewportBuilder::default()
            .with_icon(desktop_window_icon())
            .with_inner_size([1240.0, 800.0])
            .with_min_inner_size([760.0, 480.0]),
        ..Default::default()
    };
    eframe::run_native(
        WINDOWS_CLIENT_TITLE,
        options,
        Box::new(move |cc| {
            append_client_runtime_log("STARTUP_CREATOR_ENTER");
            install_ui_style(&cc.egui_ctx);
            Box::new(DesktopStartupApp::new(
                cc,
                activation_requested,
                startup_fonts,
            ))
        }),
    )
    .map_err(|error| StartupFailure::new("GTW-GUI-001", format!("无法启动图形界面：{error}")))
}

