#[derive(Clone, Debug, Eq, PartialEq)]
enum StateSnapshotSaveOutcome {
    Committed,
    CommittedWithWarning(String),
    CommittedPrivacyPending(String),
}

impl StateSnapshotSaveOutcome {
    fn warning(&self) -> Option<&str> {
        match self {
            Self::Committed => None,
            Self::CommittedWithWarning(warning) | Self::CommittedPrivacyPending(warning) => {
                Some(warning)
            }
        }
    }
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum StateReplaceOutcome {
    NotCommitted,
    Committed,
    CommittedWithWarning,
}

impl StateReplaceOutcome {
    fn is_committed(self) -> bool {
        !matches!(self, Self::NotCommitted)
    }
}

