fn utc_ymd_from_epoch_millis(epoch_millis: i64) -> (i32, i32, i32) {
    let days = epoch_millis.div_euclid(86_400_000);
    let z = days.saturating_add(719_468);
    let era = if z >= 0 { z } else { z - 146_096 } / 146_097;
    let day_of_era = z - era * 146_097;
    let year_of_era =
        (day_of_era - day_of_era / 1_460 + day_of_era / 36_524 - day_of_era / 146_096) / 365;
    let mut year = year_of_era + era * 400;
    let day_of_year = day_of_era - (365 * year_of_era + year_of_era / 4 - year_of_era / 100);
    let month_prime = (5 * day_of_year + 2) / 153;
    let day = day_of_year - (153 * month_prime + 2) / 5 + 1;
    let month = month_prime + if month_prime < 10 { 3 } else { -9 };
    year += i64::from(month <= 2);
    (year as i32, month as i32, day as i32)
}

#[cfg(target_os = "windows")]
fn local_ymd_now() -> (i32, i32, i32) {
    let mut value: WindowsSystemTime = unsafe { std::mem::zeroed() };
    unsafe { GetLocalTime(&mut value) };
    (
        i32::from(value.year),
        i32::from(value.month),
        i32::from(value.day),
    )
}

#[cfg(not(target_os = "windows"))]
fn local_ymd_now() -> (i32, i32, i32) {
    utc_ymd_from_epoch_millis(now_millis())
}

