fn desktop_sync_message(result: &sync_core::SyncClientResult) -> String {
    if !result.ok {
        if matches!(
            result.mode.as_str(),
            "workspace_binding_mismatch" | "workspace_identity_rebind_invalid"
        ) {
            return "服务器身份已变化，当前工作区不符合自动迁移条件。本机数据已保留；请退出并重新登录，再使用“下载账户数据”恢复。"
                .to_string();
        }
        return desktop_sync_error_message(&result.message);
    }
    match result.mode.as_str() {
        "registered" => "账号已创建，正在同步。".to_string(),
        "logged_in" => "登录成功，正在同步。".to_string(),
        "downloaded" => "已拉取账户里的最新数据。".to_string(),
        "downloaded_account" => "账户数据已拉取到电脑。".to_string(),
        "merged" => "电脑和账户数据已合并。".to_string(),
        "uploaded" => "已把本机最新数据同步到账户。".to_string(),
        "uploaded_local" => "本机数据已强制上传到账户。".to_string(),
        _ => {
            if result.message.trim().is_empty() {
                "同步完成。".to_string()
            } else {
                result.message.clone()
            }
        }
    }
}

fn desktop_sync_error_message(message: &str) -> String {
    let trimmed = message.trim();
    let lower = trimmed.to_lowercase();
    if lower.contains("not logged in") || lower.contains("missing sync token") {
        "未登录".to_string()
    } else if lower.contains("login expired") || lower.contains("http 401") {
        "登录过期".to_string()
    } else if lower.contains("account or password is wrong") {
        "账号或密码不对".to_string()
    } else if lower.contains("email is invalid") {
        "邮箱不对".to_string()
    } else if lower.contains("password must") {
        "密码至少 6 位".to_string()
    } else if lower.contains("account already exists") {
        "账号已存在".to_string()
    } else if lower.contains("could not connect")
        || lower.contains("connection refused")
        || lower.contains("actively refused")
    {
        "服务未启动或地址不可达".to_string()
    } else if lower.contains("timed out") || lower.contains("timeout") {
        "网络超时".to_string()
    } else if lower.contains("invalid") && lower.contains("url") {
        "地址不对".to_string()
    } else if lower.contains("unreadable response") {
        "服务响应异常".to_string()
    } else if trimmed.is_empty() {
        "同步失败".to_string()
    } else {
        trimmed.to_string()
    }
}

