    #[test]
    fn health_response_requires_exact_product_role_and_protocol_identity() {
        let trusted = json!({
            "ok": true,
            "message": "ready",
            "mode": "health",
            "productId": PRODUCT.internal_id,
            "serviceRole": "sync_server",
            "syncProtocolVersion": PRODUCT.sync_protocol_version,
            "serverBuildId": PRODUCT.app_version,
            "serverProcessName": product_identity::SYNC_SERVER_FILE_NAME,
        });
        let accepted = validate_health_response(200, &trusted.to_string());
        assert!(accepted.ok);
        assert_eq!("服务正常", accepted.message);

        for (field, value) in [
            ("productId", json!("another-product")),
            ("serviceRole", json!("web_proxy")),
            (
                "syncProtocolVersion",
                json!(PRODUCT.sync_protocol_version + 1),
            ),
        ] {
            let mut forged = trusted.clone();
            forged[field] = value;
            let rejected = validate_health_response(200, &forged.to_string());
            assert!(!rejected.ok, "unexpectedly trusted forged {field}");
            assert_eq!("目标不是兼容的十倍率同步服务", rejected.message);
        }
    }

    #[test]
    fn launcher_verification_rejects_non_pe_and_sha256_tampering() {
        let dir = temp_test_dir("launcher_integrity");
        let launcher = dir.join("launcher.exe");
        let mut pe = vec![0_u8; 128];
        pe[..2].copy_from_slice(b"MZ");
        pe[60..64].copy_from_slice(&64_u32.to_le_bytes());
        pe[64..68].copy_from_slice(b"PE\0\0");
        fs::write(&launcher, &pe).unwrap();
        let sha256 = namespace_file_sha256(&launcher).unwrap();
        verify_sync_launcher_file(&launcher, &dir, Some(pe.len() as u64), Some(&sha256)).unwrap();

        pe[100] = 1;
        fs::write(&launcher, &pe).unwrap();
        let error =
            verify_sync_launcher_file(&launcher, &dir, Some(pe.len() as u64), Some(&sha256))
                .unwrap_err();
        assert_eq!(io::ErrorKind::InvalidData, error.kind());

        fs::write(&launcher, b"not an executable").unwrap();
        assert!(verify_sync_launcher_file(&launcher, &dir, None, None).is_err());
        let _ = fs::remove_dir_all(dir);
    }

