    fn test_one_pixel_bmp() -> Vec<u8> {
        let mut bytes = Vec::with_capacity(58);
        bytes.extend_from_slice(b"BM");
        bytes.extend_from_slice(&58_u32.to_le_bytes());
        bytes.extend_from_slice(&[0; 4]);
        bytes.extend_from_slice(&54_u32.to_le_bytes());
        bytes.extend_from_slice(&40_u32.to_le_bytes());
        bytes.extend_from_slice(&1_i32.to_le_bytes());
        bytes.extend_from_slice(&1_i32.to_le_bytes());
        bytes.extend_from_slice(&1_u16.to_le_bytes());
        bytes.extend_from_slice(&24_u16.to_le_bytes());
        bytes.extend_from_slice(&[0; 24]);
        bytes.resize(58, 0x7f);
        bytes
    }

    fn test_note_snapshot_with_media(
        attachment_id: &str,
        image: &[u8],
    ) -> (String, DesktopNoteAttachment) {
        let (snapshot, mut attachments) =
            test_note_snapshot_with_media_items(&[(attachment_id, image)]);
        (snapshot, attachments.remove(0))
    }

    fn test_note_snapshot_with_media_items(
        items: &[(&str, &[u8])],
    ) -> (String, Vec<DesktopNoteAttachment>) {
        let mut snapshot = app_state_with_note("note-with-media", "Media", "", None);
        for (attachment_id, image) in items {
            let attachment = DesktopNoteAttachment {
                id: (*attachment_id).to_string(),
                kind: "IMAGE".to_string(),
                file_name: format!("{attachment_id}.bmp"),
                display_name: format!("{attachment_id}.bmp"),
                mime_type: "image/bmp".to_string(),
                width: 1,
                height: 1,
                size_bytes: image.len() as i64,
                sha256: format!("{:x}", Sha256::digest(image)),
                created_at_epoch_millis: 100,
                updated_at_epoch_millis: 100,
                ..Default::default()
            };
            snapshot = app_data::import_note_image_attachment_app_data_json(
                &snapshot,
                "note-with-media",
                &serde_json::to_string(&attachment).unwrap(),
                100,
            )
            .expect("test attachment import");
        }
        let data = decode_data(&snapshot);
        let attachments = data
            .notes
            .iter()
            .find(|note| note.id == "note-with-media")
            .expect("test note")
            .attachments
            .clone();
        (snapshot, attachments)
    }

