    fn stage_namespace_for_resume(
        legacy: &Path,
        target: &Path,
        phase: AppNamespaceMigrationPhase,
    ) -> AppNamespaceMigrationMarker {
        fs::create_dir_all(target).unwrap();
        let evidence = inspect_legacy_namespace_journal_evidence(legacy).unwrap();
        let snapshot = collect_namespace_snapshot(legacy).unwrap();
        copy_namespace_snapshot(legacy, target, &snapshot).unwrap();
        let marker = AppNamespaceMigrationMarker {
            version: APP_NAMESPACE_MIGRATION_VERSION,
            phase,
            source_root_fingerprint: namespace_root_fingerprint(legacy),
            source_snapshot_sha256: namespace_snapshot_sha256(&snapshot),
            source_file_count: snapshot.len(),
            target_snapshot_sha256: namespace_snapshot_sha256(&snapshot),
            target_file_count: snapshot.len(),
            target_immutable_snapshot_sha256: namespace_snapshot_sha256(
                &namespace_migration_immutable_snapshot(&snapshot),
            ),
            target_immutable_file_count: namespace_migration_immutable_snapshot(&snapshot).len(),
            source_journal_evidence: evidence,
        };
        write_app_namespace_migration_marker(target, &marker).unwrap();
        marker
    }

    #[test]
    fn isolated_namespace_migration_is_atomic_idempotent_and_never_reimports() {
        let dir = temp_test_dir("isolated_namespace_idempotent");
        let legacy = dir.join("GridTimerClient");
        let target = dir.join("GridTimerClientV2");
        let legacy_state = legacy
            .join("accounts")
            .join("guest")
            .join("timer_state.json");
        fs::create_dir_all(legacy_state.parent().unwrap()).unwrap();
        let original = app_data::default_app_data_json(100);
        fs::write(&legacy_state, &original).unwrap();

        ensure_isolated_app_namespace(&legacy, &target).unwrap();
        assert_eq!(
            original,
            fs::read_to_string(target.join("accounts/guest/timer_state.json")).unwrap()
        );
        assert_eq!(
            AppNamespaceMigrationPhase::Complete,
            read_app_namespace_migration_marker(&target).unwrap().phase
        );

        let changed_legacy = app_data::default_app_data_json(200);
        fs::write(&legacy_state, changed_legacy).unwrap();
        ensure_isolated_app_namespace(&legacy, &target).unwrap();
        assert_eq!(
            original,
            fs::read_to_string(target.join("accounts/guest/timer_state.json")).unwrap()
        );
    }

    #[test]
    fn isolated_namespace_migration_fails_closed_when_source_changes() {
        let dir = temp_test_dir("isolated_namespace_change");
        let legacy = dir.join("GridTimerClient");
        let target = dir.join("GridTimerClientV2");
        fs::create_dir_all(&legacy).unwrap();
        let source = legacy.join("sync_account.json");
        fs::write(&source, b"first").unwrap();

        let error = ensure_isolated_app_namespace_with_hook(&legacy, &target, || {
            fs::write(&source, b"second")
        })
        .unwrap_err();
        assert_eq!(io::ErrorKind::WouldBlock, error.kind());
        assert!(!target.exists());
        assert!(!dir.join(APP_NAMESPACE_MIGRATION_STAGE).exists());
        assert_eq!(b"second", fs::read(&source).unwrap().as_slice());
    }

    #[test]
