    #[test]
    fn incomplete_namespace_never_completes_after_legacy_source_drift() {
        for phase in [
            AppNamespaceMigrationPhase::Copied,
            AppNamespaceMigrationPhase::Finalizing,
        ] {
            let dir = temp_test_dir(match phase {
                AppNamespaceMigrationPhase::Copied => "copied_source_drift",
                _ => "finalizing_source_drift",
            });
            let legacy = dir.join("GridTimerClient");
            let target = dir.join("GridTimerClientV2");
            fs::create_dir_all(&legacy).unwrap();
            let source = legacy.join("client_settings.json");
            fs::write(&source, b"before-publish").unwrap();
            stage_namespace_for_resume(&legacy, &target, phase);
            fs::write(&source, b"legacy-changed-after-publish").unwrap();

            let error = ensure_isolated_app_namespace(&legacy, &target).unwrap_err();
            assert_eq!(io::ErrorKind::WouldBlock, error.kind());
            assert_eq!(
                phase,
                read_app_namespace_migration_marker(&target).unwrap().phase
            );
        }
    }

    #[test]
    fn finalizing_namespace_rechecks_source_after_partial_evidence_write() {
        let dir = temp_test_dir("partial_evidence_source_drift");
        let legacy = dir.join("GridTimerClient");
        let target = dir.join("GridTimerClientV2");
        fs::create_dir_all(&legacy).unwrap();
        let store = DesktopStateStore::open(desktop_state_store_path(&legacy)).unwrap();
        store
            .record(
                "owner-partial-evidence",
                &app_data::default_app_data_json(100),
                100,
                "migration-test",
            )
            .unwrap();
        let journal = store.journal_evidence().unwrap();
        let legacy_evidence = desktop_state_initialization_evidence(&legacy, &journal);
        write_desktop_state_evidence_pair(
            &desktop_state_store_marker_path(&legacy),
            &desktop_state_store_external_marker_path(&legacy),
            &legacy_evidence,
            true,
            true,
        )
        .unwrap();
        drop(store);
        let marker =
            stage_namespace_for_resume(&legacy, &target, AppNamespaceMigrationPhase::Finalizing);
        let target_journal =
            read_desktop_state_journal_evidence_read_only(&desktop_state_store_path(&target))
                .unwrap();
        let target_evidence = desktop_state_initialization_evidence(&target, &target_journal);
        write_desktop_state_marker(&desktop_state_store_marker_path(&target), &target_evidence)
            .unwrap();
        assert!(!desktop_state_store_external_marker_path(&target).exists());

        fs::write(legacy.join("changed-after-local-evidence"), b"drift").unwrap();
        let error = ensure_isolated_app_namespace(&legacy, &target).unwrap_err();
        assert_eq!(io::ErrorKind::WouldBlock, error.kind());
        assert_eq!(
            marker.phase,
            read_app_namespace_migration_marker(&target).unwrap().phase
        );
        assert!(!desktop_state_store_external_marker_path(&target).exists());
    }

