    #[test]
    fn namespace_migration_rejects_missing_or_rolled_back_legacy_journal() {
        let dir = temp_test_dir("migration_missing_and_rollback");
        let missing_legacy = dir.join("missing/GridTimerClient");
        let missing_target = dir.join("missing/GridTimerClientV2");
        fs::create_dir_all(&missing_legacy).unwrap();
        let missing_evidence = DesktopStateInitializationEvidence {
            version: DESKTOP_STATE_EVIDENCE_VERSION,
            root_fingerprint: desktop_state_root_fingerprint(&missing_legacy),
            journal_id: "a".repeat(64),
            commit_sequence: 1,
        };
        write_desktop_state_marker(
            &desktop_state_store_external_marker_path(&missing_legacy),
            &missing_evidence,
        )
        .unwrap();
        assert_eq!(
            io::ErrorKind::NotFound,
            ensure_isolated_app_namespace(&missing_legacy, &missing_target)
                .unwrap_err()
                .kind()
        );
        assert!(!missing_target.exists());

        let rollback_legacy = dir.join("rollback/GridTimerClient");
        let rollback_target = dir.join("rollback/GridTimerClientV2");
        fs::create_dir_all(&rollback_legacy).unwrap();
        let store = DesktopStateStore::open(desktop_state_store_path(&rollback_legacy)).unwrap();
        store
            .record(
                "owner-rollback",
                &app_data::default_app_data_json(100),
                100,
                "migration-test",
            )
            .unwrap();
        let journal = store.journal_evidence().unwrap();
        let local = desktop_state_initialization_evidence(&rollback_legacy, &journal);
        write_desktop_state_marker(&desktop_state_store_marker_path(&rollback_legacy), &local)
            .unwrap();
        let rolled_back = DesktopStateInitializationEvidence {
            commit_sequence: journal.commit_sequence + 1,
            ..local
        };
        write_desktop_state_marker(
            &desktop_state_store_external_marker_path(&rollback_legacy),
            &rolled_back,
        )
        .unwrap();
        drop(store);
        let error = ensure_isolated_app_namespace(&rollback_legacy, &rollback_target).unwrap_err();
        assert!(error
            .to_string()
            .contains("older than its independent external evidence"));
        assert!(!rollback_target.exists());
    }

