    #[test]
    fn isolated_namespace_migrates_actual_legacy_note_media_to_stable_workspace_key() {
        let dir = temp_test_dir("isolated_namespace_note_media");
        let legacy = dir.join("GridTimerClient");
        let target = dir.join("GridTimerClientV2");
        let legacy_state = state_path_for_user(&legacy, "");
        fs::create_dir_all(&legacy).unwrap();
        fs::write(&legacy_state, app_data::default_app_data_json(100)).unwrap();
        let source_image = dir.join("legacy-image.bmp");
        fs::write(&source_image, test_one_pixel_bmp()).unwrap();
        let workspace = AiWorkspaceIdentity {
            namespace_root: legacy.clone(),
            state_path: legacy_state.clone(),
            server_instance_id: String::new(),
            account_namespace: String::new(),
            user_id: String::new(),
        };
        let identity = workspace_note_media_identity(&workspace);
        let legacy_media_root = legacy_state_scoped_note_media_root(
            &legacy_state,
            &legacy_workspace_note_media_key(&legacy_state),
        );
        let old_store = gridtimer_native::desktop_note_media::DesktopNoteMediaStore::new_bound(
            &legacy_media_root,
            &identity,
        )
        .unwrap();
        let pending = old_store.begin_import(&source_image).unwrap();
        let attachment_id = pending.attachment_id().to_string();
        old_store.commit_import(&pending).unwrap();
        drop(old_store);

        ensure_isolated_app_namespace(&legacy, &target).unwrap();
        let target_state = state_path_for_user(&target, "");
        let copied_legacy_media_root = legacy_state_scoped_note_media_root(
            &target_state,
            &legacy_workspace_note_media_key(&legacy_state),
        );
        assert!(copied_legacy_media_root.is_dir());
        let target_workspace = AiWorkspaceIdentity {
            namespace_root: target.clone(),
            state_path: target_state.clone(),
            ..workspace
        };
        let migrated =
            note_media_store_for_workspace_in_namespaces(&target_workspace, &legacy, &target)
                .unwrap();
        assert!(migrated.blob_exists(&attachment_id).unwrap());
        assert!(!copied_legacy_media_root.exists());
        assert_eq!(
            workspace_note_media_root(&target, &stable_workspace_note_media_key(&identity),)
                .canonicalize()
                .unwrap(),
            migrated.root()
        );
    }

