    fn note_media_copy_crosses_state_parents_but_stays_anchored_to_each_namespace() {
        let dir = temp_test_dir("note_media_cross_parent_copy");
        let source_namespace = dir.join("GridTimerClient");
        let target_namespace = dir.join("GridTimerClientV2");
        fs::create_dir_all(&target_namespace).unwrap();
        let image = test_one_pixel_bmp();
        let (snapshot, attachment) =
            test_note_snapshot_with_media("attachment-cross-parent", &image);
        let source_workspace = workspace_identity_for_scope(
            &source_namespace,
            source_namespace.join("accounts/source/timer_state.json"),
            TEST_SERVER_INSTANCE_ID,
            &test_account_namespace("same-account"),
            "same-account",
        );
        let target_workspace = workspace_identity_for_scope(
            &target_namespace,
            target_namespace.join("different/parent/timer_state.json"),
            TEST_SERVER_INSTANCE_ID,
            &test_account_namespace("same-account"),
            "same-account",
        );
        let identity = workspace_note_media_identity(&source_workspace);
        let source_store = gridtimer_native::desktop_note_media::DesktopNoteMediaStore::new_bound(
            workspace_note_media_root(
                &source_namespace,
                &stable_workspace_note_media_key(&identity),
            ),
            &identity,
        )
        .unwrap();
        source_store
            .write_download_blob(
                &attachment.id,
                &attachment.sha256,
                attachment.size_bytes,
                &attachment.mime_type,
                attachment.updated_at_epoch_millis,
                &image,
            )
            .unwrap();

        let owner = desktop_state_owner(
            &target_workspace.server_instance_id,
            &target_workspace.account_namespace,
            &target_workspace.user_id,
        )
        .unwrap();
        let transaction = stage_scope_media_transaction(
            &target_namespace,
            &owner,
            &snapshot,
            &source_workspace,
            &target_workspace,
        )
        .unwrap()
        .unwrap();
        open_desktop_state_store(&target_namespace)
            .unwrap()
            .record(
                &owner,
                &snapshot,
                100,
                &scope_media_transaction_source(&transaction.manifest.tx_id),
            )
            .unwrap();
        recover_scope_media_transactions(&target_namespace).unwrap();

        let target_store = note_media_store_for_workspace(&target_workspace).unwrap();
        assert!(source_store.blob_exists(&attachment.id).unwrap());
        assert!(target_store.blob_exists(&attachment.id).unwrap());
        let expected_source = workspace_note_media_root(
            &source_namespace,
            &stable_workspace_note_media_key(&workspace_note_media_identity(&source_workspace)),
        )
        .canonicalize()
        .unwrap();
        let expected_target = workspace_note_media_root(
            &target_namespace,
            &stable_workspace_note_media_key(&workspace_note_media_identity(&target_workspace)),
        )
        .canonicalize()
        .unwrap();
        assert_eq!(expected_source.as_path(), source_store.root());
        assert_eq!(expected_target.as_path(), target_store.root());
    }

