    #[test]
    fn identity_rebind_media_conflict_fails_before_switching_scope() {
        let dir = temp_test_dir("identity_rebind_media_conflict");
        let root = dir.join("GridTimerClientV2");
        let source_image = test_one_pixel_bmp();
        let mut target_image = source_image.clone();
        *target_image.last_mut().unwrap() ^= 0x5a;
        let (snapshot, attachment) =
            test_note_snapshot_with_media("attachment-rebind-conflict", &source_image);
        let mut client = test_client_for_account_scope(&root, "source-account", snapshot.clone());
        let original_state_path = client.state_path.clone();
        let original_user_id = client.sync.user_id.clone();
        let source_workspace = client.ai_workspace_identity();
        let source_store = note_media_store_for_workspace(&source_workspace).unwrap();
        source_store
            .write_download_blob(
                &attachment.id,
                &attachment.sha256,
                attachment.size_bytes,
                &attachment.mime_type,
                attachment.updated_at_epoch_millis,
                &source_image,
            )
            .unwrap();
        let target_user_id = "target-account";
        let target_token = "target-token";
        let mut target_sync = DesktopSyncSession {
            server_instance_id: TEST_SERVER_INSTANCE_ID.to_string(),
            account_namespace: test_account_namespace(target_user_id),
            server_url: "https://sync.example.test".to_string(),
            user_id: target_user_id.to_string(),
            token_id: sync_core::token_identifier(target_token),
            token: target_token.to_string(),
            device_name: "test-device".to_string(),
            ..Default::default()
        };
        let target_workspace = workspace_identity_for_scope(
            &root,
            state_path_for_account(&root, &target_sync.account_namespace, &target_sync.user_id),
            &target_sync.server_instance_id,
            &target_sync.account_namespace,
            &target_sync.user_id,
        );
        let target_store = note_media_store_for_workspace(&target_workspace).unwrap();
        let target_sha256 = format!("{:x}", Sha256::digest(&target_image));
        target_store
            .write_download_blob(
                &attachment.id,
                &target_sha256,
                target_image.len() as i64,
                &attachment.mime_type,
                attachment.updated_at_epoch_millis,
                &target_image,
            )
            .unwrap();

        let error = client
            .prepare_identity_rebind_scope(&mut target_sync, &snapshot)
            .unwrap_err();
        assert!(matches!(
            error.kind(),
            io::ErrorKind::InvalidData | io::ErrorKind::AlreadyExists
        ));
        assert_eq!(original_state_path, client.state_path);
        assert_eq!(original_user_id, client.sync.user_id);
        assert_eq!(
            target_sha256,
            target_store
                .manifest_entry_for(&attachment.id)
                .unwrap()
                .unwrap()
                .sha256
        );
        assert!(source_store.blob_exists(&attachment.id).unwrap());
    }

    #[test]
    fn evidence_refresh_failure_reports_committed_and_keeps_media_recoverable() {
        let dir = temp_test_dir("media_state_committed_warning");
        let state_path = state_path_for_user(&dir, "");
        let owner = desktop_state_owner("", "", "").unwrap();
        let media_store =
            gridtimer_native::desktop_note_media::DesktopNoteMediaStore::new(dir.join("media"))
                .unwrap();
        let source_image = dir.join("state-commit-image.bmp");
        fs::write(&source_image, test_one_pixel_bmp()).unwrap();
        let pending = media_store.begin_import(&source_image).unwrap();
        let attachment_id = pending.attachment_id().to_string();
        let initial = note_state_with_revision("note-media-commit", "Media commit", "body", None);
        let committed_state = app_data::import_note_image_attachment_app_data_json(
            &initial,
            "note-media-commit",
            &pending.attachment_json().unwrap(),
            200,
        )
        .unwrap();

        let saved = save_state_snapshot_with_store_and_evidence_refresh(
            &dir,
            &state_path,
            &owner,
            &committed_state,
            &DesktopSyncSession::default(),
            200,
            "media-import-test",
            |_root, _store| {
                Err(io::Error::new(
                    io::ErrorKind::PermissionDenied,
                    "injected evidence refresh failure",
                ))
            },
        )
        .unwrap();
        assert!(matches!(
            saved,
            StateSnapshotSaveOutcome::CommittedWithWarning(_)
        ));
        let persisted = DesktopStateStore::open(desktop_state_store_path(&dir))
            .unwrap()
            .latest_valid(&owner, 300)
            .unwrap()
            .unwrap();
        assert_eq!(committed_state, persisted.app_data_json);
        assert!(!media_store.blob_exists(&attachment_id).unwrap());
        assert!(!media_store
            .encryption_blockers(&HashSet::from([attachment_id.clone()]))
            .unwrap()
            .is_clear());

        let referenced = HashSet::from([attachment_id.clone()]);
        let recovered = media_store.recover_pending_referenced(&referenced).unwrap();
        assert_eq!(1, recovered.recovered_count);
        assert!(media_store.blob_exists(&attachment_id).unwrap());
    }

