    #[test]
    fn media_success_confirms_only_the_exact_staged_job() {
        use gridtimer_native::desktop_background_jobs::BackgroundJobState;
        let dir = temp_test_dir("media_exact_background_receipt");
        let mut client =
            test_client_for_account_scope(&dir, "account-a", app_data::default_app_data_json(100));
        let store = client.background_job_store.clone().unwrap();
        let old = store
            .stage_job(
                BackgroundJobKind::MediaSync,
                &client.background_job_workspace_fingerprint(),
                1,
                100,
            )
            .unwrap();
        store.mark_running(&old.id, 101).unwrap();
        client.pending_reconciliation_jobs = store.recover_interrupted(200).unwrap();
        let current = client
            .stage_background_job(BackgroundJobKind::MediaSync)
            .unwrap();
        let task = SyncTaskState {
            kind: SyncTaskKind::Sync,
            phase: SyncTaskPhase::NoteMedia,
            started_at_epoch_millis: 300,
        };
        client.sync_task = Some(task);
        let (tx, rx) = mpsc::channel();
        tx.send(NoteMediaSyncTaskResult {
            background_job_id: Some(current.clone()),
            task,
            origin_workspace: client.ai_workspace_identity(),
            base_status: String::new(),
            result: Ok(Default::default()),
        })
        .unwrap();
        client.note_media_sync_result_rx = Some(rx);
        client.poll_note_media_sync_result();
        assert_eq!(
            BackgroundJobState::Completed,
            store.load(&current).unwrap().unwrap().state
        );
        assert_eq!(
            BackgroundJobState::AwaitingReconciliation,
            store.load(&old.id).unwrap().unwrap().state
        );
        assert_eq!(1, client.pending_reconciliation_jobs.len());
        assert!(client.active_background_job_id.is_none());
        // A successful media receipt starts managed local cleanup. Consume its
        // receipt and join the owned worker before removing this workspace.
        let deadline = Instant::now() + Duration::from_secs(30);
        while client.external_workspace_save_pending() || client.task_supervisor.active_count() > 0
        {
            client.poll_synced_media_cleanup();
            for task in client.task_supervisor.reap_finished() {
                assert!(!task.panicked, "media cleanup worker panicked");
            }
            assert!(Instant::now() < deadline, "media cleanup did not finish");
            thread::sleep(Duration::from_millis(5));
        }
        drop(client);
        fs::remove_dir_all(dir).unwrap();
    }

