    fn drain_draft_writer(client: &mut TimerWindowsClient) {
        let deadline = Instant::now() + Duration::from_secs(30);
        while client.persistence.pending() {
            client.poll_draft_persistence();
            assert!(
                Instant::now() < deadline,
                "draft writer stalled: {}",
                client.status
            );
            std::thread::sleep(Duration::from_millis(5));
        }
    }

    #[test]
    fn async_draft_receipt_never_clears_newer_editor_text() {
        let root = temp_test_dir("async_draft_revision");
        let mut client = test_client_for_account_scope(
            &root,
            "writer",
            app_state_with_note("n", "before", "body", None),
        );
        client.select_note_by_id("n");
        client.note_title_draft = "first".into();
        client.mark_note_dirty();
        let ctx = egui::Context::default();
        client.submit_draft_snapshot(&ctx, true);
        client.note_title_draft = "second".into();
        client.mark_note_dirty();
        drain_draft_writer(&mut client);
        assert!(
            client.note_dirty,
            "old receipt must not acknowledge new edits"
        );
        assert_eq!(client.note_title_draft, "second");
        assert_eq!(
            client
                .data
                .notes
                .iter()
                .find(|note| note.id == "n")
                .unwrap()
                .title,
            "first"
        );
        client.submit_draft_snapshot(&ctx, true);
        drain_draft_writer(&mut client);
        assert!(!client.note_dirty, "{}", client.status);
        let disk = fs::read_to_string(&client.state_path).unwrap();
        assert_eq!(
            decode_data(&disk)
                .notes
                .iter()
                .find(|note| note.id == "n")
                .unwrap()
                .title,
            "second"
        );
        drop(client);
        fs::remove_dir_all(root).unwrap();
    }

