    fn app_state_with_note(
        note_id: &str,
        title: &str,
        content: &str,
        revision: Option<(&str, &str, &str)>,
    ) -> String {
        let mut note =
            desktop_note_save_value(note_id, DesktopNoteKind::Sticky, title, content, None, 100);
        if let Some((revision_id, revision_title, revision_content)) = revision {
            note["revisions"] = json!([{
                "id": revision_id,
                "title": revision_title,
                "content": revision_content,
                "document": {
                    "markdownEnabled": true,
                    "richTextEnabled": false,
                    "richTextPlainText": revision_content,
                    "blocks": [{
                        "id": format!("{revision_id}-text"),
                        "type": "TEXT",
                        "text": revision_content
                    }]
                },
                "capturedAtEpochMillis": 50
            }]);
        }
        app_data::upsert_note_app_data_json(
            &app_data::default_app_data_json(100),
            &note.to_string(),
            100,
        )
        .unwrap()
    }

