    #[test]
    fn note_media_restore_required_schedules_only_one_app_data_retry_per_generation() {
        let dir = temp_test_dir("media_restore_retry");
        let mut client =
            test_client_for_account_scope(&dir, "account-a", app_data::default_app_data_json(100));
        let restore_summary =
            gridtimer_native::desktop_note_media_sync::DesktopNoteMediaSyncSummary {
                restore_required: true,
                current_generation: 7,
                ..Default::default()
            };
        client.sync_task = Some(SyncTaskState {
            kind: SyncTaskKind::Sync,
            phase: SyncTaskPhase::NoteMedia,
            started_at_epoch_millis: 1,
        });

        let media_task = client.sync_task.unwrap();
        let origin_workspace = client.ai_workspace_identity();
        client.finish_note_media_sync_task(NoteMediaSyncTaskResult {
            background_job_id: None,
            task: media_task,
            origin_workspace,
            base_status: "数据同步完成".to_string(),
            result: Ok(restore_summary.clone()),
        });

        assert!(client.sync_task.is_none());
        assert!(client.startup_sync_due_epoch_millis > 0);
        assert_eq!(Some(7), client.note_media_restore_retry_generation);
        assert!(client.status.contains("正在重新恢复完整快照"));

        // Model the scheduled AppData retry having been consumed. A repeated
        // response for the same server generation must not enqueue a loop.
        client.startup_sync_due_epoch_millis = 0;
        client.sync_task = Some(SyncTaskState {
            kind: SyncTaskKind::Sync,
            phase: SyncTaskPhase::NoteMedia,
            started_at_epoch_millis: 2,
        });
        let media_task = client.sync_task.unwrap();
        let origin_workspace = client.ai_workspace_identity();
        client.finish_note_media_sync_task(NoteMediaSyncTaskResult {
            background_job_id: None,
            task: media_task,
            origin_workspace,
            base_status: "数据同步完成".to_string(),
            result: Ok(restore_summary),
        });
        assert_eq!(0, client.startup_sync_due_epoch_millis);
        assert_eq!(Some(7), client.note_media_restore_retry_generation);
        assert!(client.status.contains("已尝试一次"));

        client.sync_task = Some(SyncTaskState {
            kind: SyncTaskKind::Sync,
            phase: SyncTaskPhase::NoteMedia,
            started_at_epoch_millis: 3,
        });
        let media_task = client.sync_task.unwrap();
        let origin_workspace = client.ai_workspace_identity();
        client.finish_note_media_sync_task(NoteMediaSyncTaskResult {
            background_job_id: None,
            task: media_task,
            origin_workspace,
            base_status: "数据同步完成".to_string(),
            result: Ok(Default::default()),
        });
        assert_eq!(None, client.note_media_restore_retry_generation);
        let _ = fs::remove_dir_all(dir);
    }

    #[test]
    fn note_encryption_guard_covers_current_and_historical_media_references() {
        assert!(!note_references_external_media(&DesktopNote::default()));

        let mut current_attachment = DesktopNote::default();
        current_attachment.attachments.push(DesktopNoteAttachment {
            id: "image-current".to_string(),
            ..Default::default()
        });
        assert!(note_references_external_media(&current_attachment));

        let mut current_block = DesktopNote::default();
        current_block.document.blocks.push(DesktopNoteBlock {
            block_type: "IMAGE".to_string(),
            attachment_id: Some("image-block".to_string()),
            ..Default::default()
        });
        assert!(note_references_external_media(&current_block));

        let mut recovery_point = DesktopNote::default();
        recovery_point.revisions.push(DesktopNoteRevisionSnapshot {
            attachment_ids: vec!["image-recovery".to_string()],
            ..Default::default()
        });
        assert!(note_references_external_media(&recovery_point));

        let mut product_version = DesktopNote::default();
        product_version.versions.push(DesktopNoteVersionSnapshot {
            attachments: vec![DesktopNoteAttachment {
                id: "image-version".to_string(),
                ..Default::default()
            }],
            ..Default::default()
        });
        assert!(note_references_external_media(&product_version));
    }

    #[test]
    fn compact_layout_reflows_metrics_and_note_editor_without_zero_columns() {
        assert_eq!(1, responsive_metric_column_count(200.0, 4));
        assert_eq!(2, responsive_metric_column_count(540.0, 4));
        assert_eq!(4, responsive_metric_column_count(900.0, 4));
        assert_eq!(3, responsive_metric_column_count(620.0, 3));
        assert_eq!(1, responsive_metric_column_count(900.0, 1));
        assert_eq!(1, responsive_metric_column_count(900.0, 0));
        assert!(compact_split_layout(719.0));
        assert!(!compact_split_layout(720.0));
    }

