    #[test]
    fn encrypted_sticky_version_preserves_workspace_and_plaintext_on_reselection() {
        let dir = temp_test_dir("encrypted_sticky_version_workspace");
        let password = "version-secret-123";
        let mut state = app_state_with_note_versions();
        state = add_note_to_state(&state, "note-other", "其他便签", "不可丢失的内容", 350);
        state = app_data::update_slot_title_app_data_json(&state, 1, "不可丢失的计时格", 360)
            .expect("slot title");
        let plain = decode_data(&state)
            .notes
            .into_iter()
            .find(|note| note.id == "note-versioned")
            .expect("plain note");
        let version_count_before = plain.versions.len();
        let (sealed_note_json, setup_token) = gridtimer_native::encrypt_desktop_note_json(
            &serde_json::to_string(&plain).unwrap(),
            password,
        )
        .expect("encrypt note");
        assert!(gridtimer_native::close_desktop_note_session(&setup_token));
        state = app_data::upsert_note_app_data_json(&state, &sealed_note_json, 400)
            .expect("store sealed note");

        let mut client = test_client_for_account_scope(&dir, "account-a", state);
        client.tab = AppTab::Notes;
        client.select_note_by_id("note-versioned");
        assert!(client.selected_note_is_locked());
        client.note_crypto_password_draft = password.to_string();
        client.unlock_note_encryption();
        assert_eq!("当前正文", client.note_content_draft);

        client.create_note_product_version("");

        assert_eq!(2, client.data.notes.len(), "创建版本不得清空其他便签");
        assert_eq!("不可丢失的计时格", client.data.slots[0].title);
        let other = client
            .data
            .notes
            .iter()
            .find(|note| note.id == "note-other")
            .expect("other note remains");
        assert_eq!("不可丢失的内容", note_body_text(other));
        let unlocked = client
            .selected_note()
            .expect("unlocked note remains visible");
        assert_eq!("当前正文", note_body_text(&unlocked));
        assert_eq!(version_count_before + 1, unlocked.versions.len());

        client.set_note_canvas_text("重新选择前的加密改动");
        assert!(client.note_dirty);
        client.select_note_by_id("note-versioned");
        assert_eq!("重新选择前的加密改动", client.note_content_draft);
        assert!(!client.note_dirty);
        assert!(!client.selected_note_is_locked());

        let stored = client
            .data
            .notes
            .iter()
            .find(|note| note.id == "note-versioned")
            .cloned()
            .expect("sealed note remains");
        let (reopened_json, verify_token) = gridtimer_native::unlock_desktop_note_json(
            &serde_json::to_string(&stored).unwrap(),
            password,
        )
        .expect("reopen sealed note");
        let reopened: DesktopNote = serde_json::from_str(&reopened_json).unwrap();
        assert_eq!("重新选择前的加密改动", note_body_text(&reopened));
        assert_eq!(version_count_before + 1, reopened.versions.len());
        assert!(gridtimer_native::close_desktop_note_session(&verify_token));
        client.close_note_crypto_session();
        let _ = fs::remove_dir_all(dir);
    }

