    #[test]
    fn history_search_prefers_newest_match_and_knowledge_ignores_versions() {
        let data = decode_data(&app_state_with_note_versions());
        let mut sticky = data
            .notes
            .iter()
            .find(|note| note.id == "note-versioned")
            .cloned()
            .unwrap();
        let mut newer = sticky
            .versions
            .iter()
            .find(|version| version.id == "version-old")
            .cloned()
            .unwrap();
        newer.id = "version-newer-match".to_string();
        newer.sequence = 2;
        newer.created_at_epoch_millis = 220;
        newer.updated_at_epoch_millis = 220;
        sticky.versions.push(newer);
        assert_eq!(
            Some("version-newer-match".to_string()),
            historical_note_version_for_query(&sticky, &data.note_folders, "松针文字")
        );
        let old = sticky
            .versions
            .iter_mut()
            .find(|version| version.id == "version-old")
            .unwrap();
        old.attachments.push(DesktopNoteAttachment {
            id: "old-image".to_string(),
            display_name: "只在旧版的收据图".to_string(),
            mime_type: "image/png".to_string(),
            ..Default::default()
        });
        assert!(note_search_text(&sticky, &data.note_folders).contains("只在旧版的收据图"));
        assert_eq!(
            Some("version-old".to_string()),
            historical_note_version_for_query(&sticky, &data.note_folders, "只在旧版的收据图")
        );

        sticky.kind = "DOCUMENT".to_string();
        assert!(!note_search_text(&sticky, &data.note_folders).contains("松针文字"));
        assert_eq!(
            None,
            historical_note_version_for_query(&sticky, &data.note_folders, "松针文字")
        );
    }

