    #[test]
    fn ai_result_after_workspace_switch_is_discarded_without_cross_account_write() {
        let dir = temp_test_dir("ai_workspace_switch");
        let account_state = app_state_with_note("note-a", "甲", "甲正文", None);
        let mut client = test_client_for_account_scope(&dir, "account-a", account_state);
        let origin = client.data.notes[0].clone();
        let origin_content = note_body_text(&origin);
        client.load_note_draft_without_flush(&origin);
        let origin_workspace = client.ai_workspace_identity();
        let account_state_path = client.state_path.clone();
        let (tx, rx) = mpsc::channel();
        tx.send(AiNoteTaskResult {
            origin_workspace,
            origin_note_id: origin.id.clone(),
            origin_title: origin.title.clone(),
            origin_content,
            origin_kind: DesktopNoteKind::Sticky,
            origin_updated_at_epoch_millis: origin.updated_at_epoch_millis,
            result: ai_client::AiCompletionResult::ok("不得写入访客工作区".to_string()),
        })
        .unwrap();
        client.ai_pending = true;
        client.ai_result_rx = Some(rx);

        let mut guest_sync = DesktopSyncSession {
            server_url: client.sync.server_url.clone(),
            device_name: client.sync.device_name.clone(),
            ..DesktopSyncSession::default()
        };
        client
            .switch_state_scope(&mut guest_sync, false)
            .expect("switch to guest workspace");
        let guest_before = client.state_json.clone();

        client.poll_ai_result();

        assert!(!client.ai_pending);
        assert!(client.ai_result_rx.is_none());
        assert!(client.pending_ai_note_result.is_none());
        assert_eq!(guest_before, client.state_json);
        assert!(!client.state_json.contains("不得写入访客工作区"));
        assert!(client.status.contains("未写入当前账号"));
        let account_after = load_state_json(&account_state_path, now_millis()).value;
        assert!(account_after.contains("甲正文"));
        assert!(!account_after.contains("不得写入访客工作区"));
        let _ = fs::remove_dir_all(dir);
    }

