    #[test]
    fn exact_download_is_rejected_if_local_state_changed_after_the_request() {
        let dir = temp_test_dir("download_inflight_edit_rejected");
        let initial = app_state_with_note("note-a", "标题", "初始正文", None);
        let mut client = test_client_for_account_scope(&dir, "account-a", initial.clone());
        client.sync.last_message = "上一次真实成功".to_string();
        client.sync.last_sync_at_epoch_millis = 123;
        client.sync_task = Some(SyncTaskState {
            kind: SyncTaskKind::Download,
            phase: SyncTaskPhase::AppData,
            started_at_epoch_millis: now_millis(),
        });
        let selected = client.data.notes[0].clone();
        client.load_note_draft_without_flush(&selected);
        client.set_note_canvas_text("请求后本机新写内容");
        client.sync_task = None;
        let remote = add_note_to_state(&initial, "note-a", "标题", "账户端正文", 300);
        let response = sync_core::SyncClientResult {
            mode: "downloaded_account".to_string(),
            ..bound_app_data_response(&client, remote)
        };
        let mut identity = bound_result_expectation(&client);
        if let SyncResultIdentityExpectation::BoundAccount { operation, .. } = &mut identity {
            *operation = BoundSyncOperation::ExplicitDownload;
        }
        let sync_before = serde_json::to_value(&client.sync).unwrap();

        let rejected =
            client.apply_sync_result(&serde_json::to_string(&response).unwrap(), false, &identity);

        assert!(!rejected.ok);
        assert!(client.status.contains("本机数据又发生变化"));
        assert_eq!(initial, client.state_json);
        assert_eq!("请求后本机新写内容", client.note_content_draft);
        assert!(client.note_dirty);
        assert_eq!(sync_before, serde_json::to_value(&client.sync).unwrap());
        let _ = fs::remove_dir_all(dir);
    }

    fn pending_revocation(token: &str) -> PendingTokenRevocation {
        PendingTokenRevocation {
            server_url: "https://sync.example.test".to_string(),
            user_id: "account-a".to_string(),
            token_id: "token-id-a".to_string(),
            token: token.to_string(),
            queued_at_epoch_millis: 100,
            ready_to_revoke: true,
        }
    }

    #[test]
    fn successful_revocation_removes_encrypted_queue_and_backup() {
        let dir = temp_test_dir("revocation_success");
        let path = dir.join("sync_account.revocations.secrets");
        let token = "revoked-secret-token";
        let item = pending_revocation(token);
        let key = pending_token_revocation_key(&item);
        let mut queue = PendingTokenRevocationQueue { items: vec![item] };
        save_pending_token_revocations(&path, &queue).expect("save pending");

        assert!(remove_pending_token_revocation(&mut queue, &key));
        save_pending_token_revocations(&path, &queue).expect("save cleared");

        assert!(load_pending_token_revocations(&path).value.items.is_empty());
        for encrypted_path in [&path, &backup_path(&path)] {
            let raw = fs::read(encrypted_path).expect("encrypted queue");
            #[cfg(target_os = "windows")]
            assert!(raw.starts_with(DPAPI_SECRET_HEADER));
            assert!(!String::from_utf8_lossy(&raw).contains(token));
        }
        let _ = fs::remove_dir_all(dir);
    }

    #[test]
    fn failed_revocation_stays_in_dpapi_queue_without_plaintext_backup() {
        let dir = temp_test_dir("revocation_failure");
        let path = dir.join("sync_account.revocations.secrets");
        let token = "pending-secret-token";
        let queue = PendingTokenRevocationQueue {
            items: vec![pending_revocation(token)],
        };
        save_pending_token_revocations(&path, &queue).expect("save pending");
        let calls = std::cell::Cell::new(0usize);

        let revoked = post_logout_once_with("https://sync.example.test", token, |url, sent| {
            calls.set(calls.get() + 1);
            assert_eq!("https://sync.example.test/v1/logout", url);
            assert_eq!(token, sent);
            false
        });

        assert!(!revoked);
        assert_eq!(1, calls.get());
        assert_eq!(1, load_pending_token_revocations(&path).value.items.len());
        for encrypted_path in [&path, &backup_path(&path)] {
            let raw = fs::read(encrypted_path).expect("encrypted queue");
            #[cfg(target_os = "windows")]
            assert!(raw.starts_with(DPAPI_SECRET_HEADER));
            assert!(!String::from_utf8_lossy(&raw).contains(token));
        }
        let _ = fs::remove_dir_all(dir);
    }

