    #[test]
    fn identity_rebind_commits_merged_workspace_before_session_and_survives_restart() {
        let dir = temp_test_dir("identity_rebind_restart");
        let local = app_state_with_note("local-note", "Local", "offline edit", None);
        let remote = app_state_with_note("remote-note", "Remote", "account baseline", None);
        let mut client = test_client_for_account_scope(&dir, "account-a", local);
        let (workspace_id, _) = prepare_generation_zero_rebind_workspace(&mut client);
        let old_state_path = client.state_path.clone();
        let identity = bound_result_expectation(&client);
        let response = workspace_identity_rebind_result(&client, &workspace_id, remote);

        let applied =
            client.apply_sync_result(&serde_json::to_string(&response).unwrap(), false, &identity);

        assert!(applied.ok, "rebind status: {}", client.status);
        assert!(applied.workspace_identity_rebound);
        assert_ne!(old_state_path, client.state_path);
        assert_eq!(response.server_instance_id, client.sync.server_instance_id);
        assert_eq!(response.account_namespace, client.sync.account_namespace);
        assert_eq!(response.restore_receipt, client.sync.restore_receipt);
        let rebound_checkpoint = workspace_checkpoint_for_account(
            &client.sync,
            &client.sync.server_instance_id,
            &client.sync.account_namespace,
            &client.sync.user_id,
        );
        assert_eq!(workspace_id, rebound_checkpoint.workspace_id);
        assert!(rebound_checkpoint.workspace_capability.is_empty());
        assert!(client.data.notes.iter().any(|note| note.id == "local-note"));
        assert!(client
            .data
            .notes
            .iter()
            .any(|note| note.id == "remote-note"));

        let (reloaded_sync, _) =
            load_committed_sync_session(&client.sync_path, &client.secrets_path);
        assert_eq!(
            response.server_instance_id,
            reloaded_sync.value.server_instance_id
        );
        assert_eq!(
            response.restore_receipt,
            reloaded_sync.value.restore_receipt
        );
        let owner = desktop_state_owner(
            &reloaded_sync.value.server_instance_id,
            &reloaded_sync.value.account_namespace,
            &reloaded_sync.value.user_id,
        )
        .unwrap();
        let (reloaded_state, _) =
            load_state_snapshot_with_store(&dir, &client.state_path, &owner, now_millis()).unwrap();
        let reloaded_data = decode_data(&reloaded_state.value);
        assert!(reloaded_data
            .notes
            .iter()
            .any(|note| note.id == "local-note"));
        assert!(reloaded_data
            .notes
            .iter()
            .any(|note| note.id == "remote-note"));

        client.sync = reloaded_sync.value;
        client.state_json = reloaded_state.value;
        client.data = reloaded_data;
        let committed_proof = "e".repeat(64);
        let confirmation = sync_core::SyncClientResult {
            ok: true,
            current_committed: true,
            user_id: client.sync.user_id.clone(),
            server_instance_id: client.sync.server_instance_id.clone(),
            account_namespace: client.sync.account_namespace.clone(),
            workspace_id: workspace_id.clone(),
            workspace_proof: committed_proof.clone(),
            token_id: client.sync.token_id.clone(),
            app_data_json: Some(client.state_json.clone()),
            current_generation: 0,
            mode: "unchanged".to_string(),
            ..Default::default()
        };
        let confirmation_identity = bound_result_expectation(&client);
        let confirmed = client.apply_sync_result(
            &serde_json::to_string(&confirmation).unwrap(),
            false,
            &confirmation_identity,
        );

        assert!(confirmed.ok, "confirmation status: {}", client.status);
        assert!(client.sync.restore_receipt.is_empty());
        let confirmed_checkpoint = workspace_checkpoint_for_account(
            &client.sync,
            &client.sync.server_instance_id,
            &client.sync.account_namespace,
            &client.sync.user_id,
        );
        assert_eq!(workspace_id, confirmed_checkpoint.workspace_id);
        assert_eq!(committed_proof, confirmed_checkpoint.workspace_capability);
        assert!(load_sync_secrets(&client.secrets_path)
            .value
            .restore_receipt
            .is_empty());
        let _ = fs::remove_dir_all(dir);
    }

    #[test]
    fn identity_rebind_rejects_forged_force_and_nonzero_variants_without_state_change() {
        let dir = temp_test_dir("identity_rebind_rejections");
        let local = app_state_with_note("local-note", "Local", "keep me", None);
        let remote = app_state_with_note("remote-note", "Remote", "baseline", None);
        let mut client = test_client_for_account_scope(&dir, "account-a", local.clone());
        let (workspace_id, _) = prepare_generation_zero_rebind_workspace(&mut client);
        let identity = bound_result_expectation(&client);
        let response = workspace_identity_rebind_result(&client, &workspace_id, remote);
        assert!(validate_sync_result_identity(&response, &identity).is_ok());
        let boundary_message = desktop_sync_message(&sync_core::SyncClientResult {
            ok: false,
            mode: "workspace_binding_mismatch".to_string(),
            message: "Sync workspace identity does not match the authenticated account."
                .to_string(),
            ..Default::default()
        });
        assert!(boundary_message.contains("本机数据已保留"));
        assert!(boundary_message.contains("退出并重新登录"));
        assert!(boundary_message.contains("下载账户数据"));

        for operation in [
            BoundSyncOperation::ForceUpload,
            BoundSyncOperation::ExplicitDownload,
            BoundSyncOperation::NamespaceBootstrapDownload,
        ] {
            let mut forced = identity.clone();
            if let SyncResultIdentityExpectation::BoundAccount {
                operation: request_operation,
                ..
            } = &mut forced
            {
                *request_operation = operation;
            }
            assert!(validate_sync_result_identity(&response, &forced).is_err());
        }

        let mut nonzero_response = response.clone();
        nonzero_response.current_generation = 1;
        assert!(validate_sync_result_identity(&nonzero_response, &identity).is_err());

        let mut nonzero_request = identity.clone();
        if let SyncResultIdentityExpectation::BoundAccount {
            acknowledged_generation,
            ..
        } = &mut nonzero_request
        {
            *acknowledged_generation = 1;
        }
        assert!(validate_sync_result_identity(&response, &nonzero_request).is_err());

        let mut wrong_workspace = response.clone();
        wrong_workspace.workspace_id = "f".repeat(64);
        assert!(validate_sync_result_identity(&wrong_workspace, &identity).is_err());

        let mut missing_old_proof = identity.clone();
        if let SyncResultIdentityExpectation::BoundAccount {
            workspace_proof, ..
        } = &mut missing_old_proof
        {
            workspace_proof.clear();
        }
        assert!(validate_sync_result_identity(&response, &missing_old_proof).is_err());

        let sync_before = serde_json::to_value(&client.sync).unwrap();
        let state_path_before = client.state_path.clone();
        let mut forced = identity;
        if let SyncResultIdentityExpectation::BoundAccount { operation, .. } = &mut forced {
            *operation = BoundSyncOperation::ForceUpload;
        }
        let rejected =
            client.apply_sync_result(&serde_json::to_string(&response).unwrap(), false, &forced);
        assert!(!rejected.ok);
        assert_eq!(sync_before, serde_json::to_value(&client.sync).unwrap());
        assert_eq!(state_path_before, client.state_path);
        assert_eq!(local, client.state_json);
        let _ = fs::remove_dir_all(dir);
    }

