        let workspace_id = workspace_checkpoint_for_account(
            &client.sync,
            &server_instance_id,
            &account_namespace,
            &user_id,
        )
        .workspace_id;
        remember_account_generation_and_capability(
            &mut client.sync,
            &server_instance_id,
            &account_namespace,
            &user_id,
            0,
            &workspace_id,
            &"e".repeat(64),
        );
