        assert!(!rejected.ok);
        assert_eq!(TEST_SERVER_INSTANCE_ID, client.sync.server_instance_id);
        assert_eq!(stable_namespace, client.sync.account_namespace);
        assert_eq!(stable_state_path, client.state_path);
