    #[cfg(target_os = "windows")]
    #[test]
    fn versioned_activation_preserves_same_or_newer_running_version_and_is_root_bound() {
        let parent = temp_test_dir("versioned_instance_activation");
        let root = parent.join("state-root");
        let other = parent.join("other-root");
        fs::create_dir_all(&root).unwrap();
        fs::create_dir_all(&other).unwrap();
        let activate = Arc::new(AtomicBool::new(false));
        let upgrade = Arc::new(WindowsUpgradeRequestSignal::default());
        let server = WindowsClientActivationServer::start_with_upgrade(
            &root,
            Arc::clone(&activate),
            Arc::clone(&upgrade),
        )
        .unwrap();
        assert_eq!(
            request_versioned_windows_client_open(&root, WINDOWS_CLIENT_VERSION).unwrap(),
            ExistingClientOpen::Versioned {
                running: WINDOWS_CLIENT_VERSION.into(),
                effect: desktop_instance_protocol::OpenEffect::Activate
            }
        );
        assert_eq!(
            request_versioned_windows_client_open(&root, "0.0.0.0").unwrap(),
            ExistingClientOpen::Versioned {
                running: WINDOWS_CLIENT_VERSION.into(),
                effect: desktop_instance_protocol::OpenEffect::Activate
            }
        );
        assert!(!upgrade.has_pending());
        assert_ne!(
            windows_client_activation_pipe_name(&root).unwrap(),
            windows_client_activation_pipe_name(&other).unwrap()
        );
        assert!(exchange_windows_client_activation(
            &other,
            desktop_instance_protocol::LEGACY_REQUEST,
            desktop_instance_protocol::LEGACY_CONSUMED
        )
        .unwrap()
        .is_none());
        assert!(!upgrade.has_pending());
        let mut version =
            desktop_instance_protocol::release_version(WINDOWS_CLIENT_VERSION).unwrap();
        version[3] += 1;
        let next = format!(
            "{}.{}.{}.{}",
            version[0], version[1], version[2], version[3]
        );
        assert_eq!(
            request_versioned_windows_client_open(&root, &next).unwrap(),
            ExistingClientOpen::Versioned {
                running: WINDOWS_CLIENT_VERSION.into(),
                effect: desktop_instance_protocol::OpenEffect::Upgrade
            }
        );
        let started = Instant::now();
        while !upgrade.has_pending() && started.elapsed() < Duration::from_secs(2) {
            thread::sleep(Duration::from_millis(10));
        }
        assert!(upgrade.has_pending());
        assert!(activate.load(AtomicOrdering::Acquire));
        let _ = exchange_windows_client_activation(
            &root,
            desktop_instance_protocol::CANCEL_REQUEST,
            desktop_instance_protocol::VERSION_CONSUMED,
        )
        .unwrap();
        let started = Instant::now();
        while upgrade.has_pending() && started.elapsed() < Duration::from_secs(2) {
            thread::sleep(Duration::from_millis(10));
        }
        assert!(!upgrade.has_pending());
        drop(server);
        fs::remove_dir_all(parent).unwrap();
    }
