    #[test]
    fn canvas_structural_edit_round_trips_through_undo_and_redo() {
        let dir = temp_test_dir("canvas_undo_redo");
        let state = app_state_with_note("note-1", "标题", "正文", None);
        let mut client = test_client_for_account_scope(&dir, "account-a", state);
        client.select_note_by_id("note-1");
        let original_ids = client
            .note_blocks_draft
            .iter()
            .map(|block| block.id.clone())
            .collect::<Vec<_>>();

        client.insert_note_text_block("第二段");
        let edited_ids = client
            .note_blocks_draft
            .iter()
            .map(|block| block.id.clone())
            .collect::<Vec<_>>();
        assert_eq!(2, edited_ids.len());
        assert_ne!(original_ids, edited_ids);

        client.undo_note_draft();
        assert_eq!(
            original_ids,
            client
                .note_blocks_draft
                .iter()
                .map(|block| block.id.clone())
                .collect::<Vec<_>>()
        );
        assert_eq!("正文", client.note_content_draft);

        client.redo_note_draft();
        assert_eq!(
            edited_ids,
            client
                .note_blocks_draft
                .iter()
                .map(|block| block.id.clone())
                .collect::<Vec<_>>()
        );
        assert_eq!("正文\n\n第二段", client.note_content_draft);
        let _ = fs::remove_dir_all(dir);
    }

