    #[test]
    fn appearance_card_pointer_click_reports_a_selection_change() {
        let ctx = egui::Context::default();
        let screen_rect = egui::Rect::from_min_size(egui::Pos2::ZERO, egui::vec2(320.0, 180.0));
        let render = |events| {
            let mut result = (egui::Rect::NOTHING, false);
            let _ = ctx.run(
                egui::RawInput {
                    screen_rect: Some(screen_rect),
                    events,
                    ..Default::default()
                },
                |ctx| {
                    egui::CentralPanel::default().show(ctx, |ui| {
                        let response = desktop_theme_choice(
                            ui,
                            ThemePreference::Dark,
                            ThemePreference::System,
                            "深色",
                            92.0,
                        );
                        result = (response.rect, response.changed());
                    });
                },
            );
            result
        };

        let (card_rect, _) = render(vec![]);
        let click_pos = card_rect.center();
        let (_, pressed_changed) = render(vec![
            egui::Event::PointerMoved(click_pos),
            egui::Event::PointerButton {
                pos: click_pos,
                button: egui::PointerButton::Primary,
                pressed: true,
                modifiers: egui::Modifiers::NONE,
            },
        ]);
        assert!(!pressed_changed, "selection must commit on pointer release");
        let (_, released_changed) = render(vec![egui::Event::PointerButton {
            pos: click_pos,
            button: egui::PointerButton::Primary,
            pressed: false,
            modifiers: egui::Modifiers::NONE,
        }]);

        assert!(
            released_changed,
            "an unselected appearance card click must reach the theme handler"
        );
    }

