    #[test]
    fn theme_click_path_stays_constant_with_a_large_workspace() {
        let dir = temp_test_dir("desktop_theme_click_perf");
        let mut client =
            test_client_for_account_scope(&dir, "theme-click-perf", knowledge_fixture_state());
        let template = client.data.notes.first().cloned().unwrap();
        for index in 0..2_000 {
            let mut note = template.clone();
            note.id = format!("perf-theme-{index}");
            note.title = format!("性能样本 {index}");
            client.data.notes.push(note);
        }
        client.state_json = serde_json::to_string(&client.data).unwrap();

        let mut samples = Vec::with_capacity(100);
        for index in 0..100 {
            let target = if index % 2 == 0 { 2 } else { 1 };
            let started = Instant::now();
            assert!(client.set_desktop_theme(target));
            samples.push(started.elapsed());
        }
        samples.sort_unstable();
        let p95 = samples[94];
        let worst = samples[99];
        println!(
            "THEME_CLICK_PERF state_bytes={} notes={} p95_ns={} worst_ns={}",
            client.state_json.len(),
            client.data.notes.len(),
            p95.as_nanos(),
            worst.as_nanos()
        );
        assert!(
            p95 < Duration::from_millis(2),
            "theme click p95 was {p95:?} for a large workspace"
        );
        drop(client);
        fs::remove_dir_all(dir).unwrap();
    }

