    #[test]
    fn account_scope_paths_are_contained_and_collision_resistant() {
        let dir = temp_test_dir("account_paths");
        let first = state_path_for_user(&dir, "same/../../account");
        let second = state_path_for_user(&dir, "same\\..\\..\\account");
        let unicode = state_path_for_user(&dir, "账户/一");
        let namespace_a = state_path_for_account(
            &dir,
            "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa",
            "shared-user-id",
        );
        let namespace_b = state_path_for_account(
            &dir,
            "bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb",
            "shared-user-id",
        );

        assert!(first.starts_with(dir.join("accounts")));
        assert!(second.starts_with(dir.join("accounts")));
        assert!(unicode.starts_with(dir.join("accounts")));
        assert_ne!(first, second);
        assert_ne!(first, unicode);
        assert_ne!(namespace_a, namespace_b);
        assert!(namespace_a.starts_with(dir.join("accounts")));
        assert!(namespace_b.starts_with(dir.join("accounts")));
        assert_eq!(
            Some("timer_state.json"),
            first.file_name().and_then(|name| name.to_str())
        );
        let _ = fs::remove_dir_all(dir);
    }

    #[test]
    fn login_scope_never_seeds_from_previous_account() {
        let dir = temp_test_dir("account_switching");
        let mut account_a_value =
            serde_json::from_str::<Value>(&app_data::default_app_data_json(100)).unwrap();
        account_a_value["slots"][0]["title"] = json!("account A only");
        account_a_value["slots"][0]["updatedAt"] = json!(100);
        let account_a = serde_json::to_string(&account_a_value).unwrap();
        let mut account_b_value =
            serde_json::from_str::<Value>(&app_data::default_app_data_json(200)).unwrap();
        account_b_value["slots"][0]["title"] = json!("account B only");
        account_b_value["slots"][0]["updatedAt"] = json!(200);
        let account_b = serde_json::to_string(&account_b_value).unwrap();
        let account_b_path = state_path_for_user(&dir, "account-b");
        atomic_save_text(&account_b_path, &account_b, |raw| {
            app_data::sanitize_app_data_json(raw, 300)
        })
        .expect("save account B");

        let existing_b = state_json_for_scope(&account_b_path, &account_a, false, 300);
        assert_eq!(
            app_data::sanitize_app_data_json(&account_b, 300).unwrap(),
            existing_b
        );
        assert_ne!(
            app_data::sanitize_app_data_json(&account_a, 300).unwrap(),
            existing_b
        );

        let missing_login_path = state_path_for_user(&dir, "new-login-account");
        let new_login = state_json_for_scope(&missing_login_path, &account_a, false, 300);
        assert_eq!(app_data::default_app_data_json(300), new_login);
        assert_ne!(account_a, new_login);

        let missing_registration_path = state_path_for_user(&dir, "new-registration-account");
        let new_registration =
            state_json_for_scope(&missing_registration_path, &account_a, true, 300);
        assert_eq!(account_a, new_registration);
        let _ = fs::remove_dir_all(dir);
    }

