    #[test]
    fn paired_sync_commits_recover_the_previous_pair_after_a_torn_write() {
        let dir = temp_test_dir("paired_sync_torn_write");
        let public_path = dir.join("sync_account.json");
        let secrets_path = dir.join("sync_account.secrets");
        let account_a = bound_sync_session("account-a", "token-a");
        let account_b = bound_sync_session("account-b", "token-b");
        let account_c = bound_sync_session("account-c", "token-c");
        save_sync_files(&public_path, &secrets_path, &account_a).unwrap();
        save_sync_files(&public_path, &secrets_path, &account_b).unwrap();

        // Simulate power loss after the encrypted half of C was committed but
        // before its public identity file was replaced.
        let (_, account_c_secrets) = prepare_sync_commit(&account_c).unwrap();
        save_sync_secrets(&secrets_path, &account_c_secrets).unwrap();

        let (loaded, rewrite_required) = load_committed_sync_session(&public_path, &secrets_path);
        assert!(rewrite_required);
        assert_eq!("account-b", loaded.value.user_id);
        assert_eq!("token-b", loaded.value.token);
        assert!(sync_identity_is_bound(&loaded.value));
        let _ = fs::remove_dir_all(dir);
    }

    #[test]
    fn torn_logout_never_resurrects_the_previous_token_backup() {
        let dir = temp_test_dir("paired_sync_torn_logout");
        let public_path = dir.join("sync_account.json");
        let secrets_path = dir.join("sync_account.secrets");
        let account = bound_sync_session("account-a", "token-a");
        save_sync_files(&public_path, &secrets_path, &account).unwrap();

        let guest = DesktopSyncSession::default();
        let (_, guest_secrets) = prepare_sync_commit(&guest).unwrap();
        save_sync_secrets(&secrets_path, &guest_secrets).unwrap();

        let (loaded, rewrite_required) = load_committed_sync_session(&public_path, &secrets_path);
        assert!(rewrite_required);
        assert!(loaded.value.user_id.is_empty());
        assert!(loaded.value.token.is_empty());
        assert!(loaded.value.token_id.is_empty());
        assert!(!sync_identity_is_bound(&loaded.value));
        let _ = fs::remove_dir_all(dir);
    }

