        let mut state: Value = serde_json::from_str(&app_data::default_app_data_json(100)).unwrap();
        state["sessions"] = json!([{
            "id": "must-survive",
            "slotId": 1,
            "startedAtEpochMillis": 10,
            "endedAtEpochMillis": 20,
            "durationMillis": 10,
            "updatedAtEpochMillis": 20
        }]);
