    #[test]
    fn independent_sequence_evidence_rejects_an_older_but_valid_database_copy() {
        let dir = temp_test_dir("desktop_journal_valid_rollback");
        let state_path = state_path_for_user(&dir, "");
        let owner = desktop_state_owner("", "", "").unwrap();
        let first = app_data::default_app_data_json(100);
        fs::write(&state_path, &first).unwrap();
        load_state_json_with_store(&dir, &state_path, &owner, 100).unwrap();
        let database_path = desktop_state_store_path(&dir);
        let older_copy = dir.join("older_journal_copy.sqlite3");
        rusqlite::Connection::open(&database_path)
            .unwrap()
            .execute_batch("PRAGMA wal_checkpoint(TRUNCATE);")
            .unwrap();
        fs::copy(&database_path, &older_copy).unwrap();

        let mut newer: Value = serde_json::from_str(&first).unwrap();
        newer["sessions"] = json!([{
            "id": "newer-durable-session",
            "slotId": 1,
            "startedAtEpochMillis": 200,
            "endedAtEpochMillis": 300,
            "durationMillis": 100,
            "updatedAtEpochMillis": 300
        }]);
        let newer = app_data::sanitize_app_data_json(&newer.to_string(), 300).unwrap();
        save_state_snapshot_with_store(
            &dir,
            &state_path,
            &owner,
            &newer,
            &DesktopSyncSession::default(),
            300,
            "local_save",
        )
        .unwrap();
        rusqlite::Connection::open(&database_path)
            .unwrap()
            .execute_batch("PRAGMA wal_checkpoint(TRUNCATE);")
            .unwrap();
        let database_name = database_path.file_name().unwrap().to_string_lossy();
        for suffix in ["-wal", "-shm"] {
            let sidecar = database_path.with_file_name(format!("{database_name}{suffix}"));
            if sidecar.exists() {
                fs::remove_file(sidecar).unwrap();
            }
        }
        fs::copy(&older_copy, &database_path).unwrap();

        let error = load_state_json_with_store(&dir, &state_path, &owner, 400).unwrap_err();
        assert!(error.to_string().contains("rolled back"));
        assert_eq!(newer, fs::read_to_string(&state_path).unwrap());
        let _ = fs::remove_file(desktop_state_store_external_marker_path(&dir));
        let _ = fs::remove_dir_all(dir);
    }

