    #[test]
    fn database_commit_ahead_of_both_markers_is_recovered_after_a_crash_window() {
        let dir = temp_test_dir("desktop_journal_marker_lag");
        let state_path = state_path_for_user(&dir, "");
        let owner = desktop_state_owner("", "", "").unwrap();
        let first = app_data::default_app_data_json(100);
        fs::write(&state_path, &first).unwrap();
        load_state_json_with_store(&dir, &state_path, &owner, 100).unwrap();
        let store = open_desktop_state_store(&dir).unwrap();
        let before = store.journal_evidence().unwrap();
        let mut second: Value = serde_json::from_str(&first).unwrap();
        second["sessions"] = json!([{
            "id": "committed-before-marker-crash",
            "slotId": 1,
            "startedAtEpochMillis": 200,
            "endedAtEpochMillis": 300,
            "durationMillis": 100,
            "updatedAtEpochMillis": 300
        }]);
        let second = app_data::sanitize_app_data_json(&second.to_string(), 300).unwrap();
        let protected_sync_state = protected_workspace_sync_state_for_store(
            &store,
            &owner,
            &DesktopSyncSession::default(),
            300,
        )
        .unwrap();
        store
            .record_with_sync_state(
                &owner,
                &second,
                &protected_sync_state,
                300,
                "injected_crash_window",
            )
            .unwrap();
        let committed = store.journal_evidence().unwrap();
        assert_eq!(before.commit_sequence + 1, committed.commit_sequence);
        for path in [
            desktop_state_store_marker_path(&dir),
            desktop_state_store_external_marker_path(&dir),
        ] {
            let DesktopStateMarkerRead::Valid(evidence) =
                read_desktop_state_marker(&dir, &path).unwrap()
            else {
                panic!("expected the pre-crash evidence to remain readable");
            };
            assert_eq!(before.journal_id, evidence.journal_id);
            assert_eq!(before.commit_sequence, evidence.commit_sequence);
            assert!(evidence.commit_sequence < committed.commit_sequence);
        }
        drop(store);

        let (recovered, recovered_sync_state) =
            load_state_snapshot_with_store(&dir, &state_path, &owner, 400).unwrap();

        assert_eq!(second, recovered.value);
        assert_eq!(protected_sync_state, recovered_sync_state);
        assert_eq!(second, fs::read_to_string(&state_path).unwrap());
        // Recovery also commits provenance for the preserved old mirror and
        // replacement primary. Compare markers with the final journal event,
        // without using the opener that would repair those markers itself.
        let recovered_evidence =
            read_desktop_state_journal_evidence_read_only(&desktop_state_store_path(&dir)).unwrap();
        assert_eq!(committed.journal_id, recovered_evidence.journal_id);
        assert!(recovered_evidence.commit_sequence >= committed.commit_sequence);
        for path in [
            desktop_state_store_marker_path(&dir),
            desktop_state_store_external_marker_path(&dir),
        ] {
            let DesktopStateMarkerRead::Valid(evidence) =
                read_desktop_state_marker(&dir, &path).unwrap()
            else {
                panic!("expected repaired v2 evidence");
            };
            assert_eq!(recovered_evidence.journal_id, evidence.journal_id);
            assert_eq!(recovered_evidence.commit_sequence, evidence.commit_sequence);
        }
        let _ = fs::remove_file(desktop_state_store_external_marker_path(&dir));
        let _ = fs::remove_dir_all(dir);
    }

