    #[test]
    fn media_preflight_failure_replaces_stale_success_without_advancing_sync_time() {
        for failed_to_start in [false, true] {
            let dir = temp_test_dir("preflight_status_durability");
            let mut client = test_client_for_account_scope(
                &dir,
                "account-a",
                app_data::default_app_data_json(100),
            );
            client.sync.last_message = "previous-success".to_string();
            client.sync.last_sync_at_epoch_millis = 123;
            client.persist_sync().unwrap();
            let state_before = client.state_json.clone();
            let task = SyncTaskState {
                kind: SyncTaskKind::Sync,
                phase: SyncTaskPhase::NoteMediaPreflight,
                started_at_epoch_millis: 200,
            };
            client.sync_task = Some(task);
            client.finish_note_media_sync_task(NoteMediaSyncTaskResult {
                background_job_id: None,
                task,
                origin_workspace: client.ai_workspace_identity(),
                base_status: "pending".to_string(),
                result: if failed_to_start {
                    Err("media-store-unavailable".to_string())
                } else {
                    Ok(
                        gridtimer_native::desktop_note_media_sync::DesktopNoteMediaSyncSummary {
                            conflicts: 1,
                            ..Default::default()
                        },
                    )
                },
            });
            assert!(client.sync_task.is_none());
            assert!(client.sync_result_rx.is_none());
            assert_eq!(state_before, client.state_json);
            let outcome = client.sync.last_message.clone();
            assert_ne!("previous-success", outcome);
            // A timer save can replace the top bar but must not hide this outcome.
            client.status = "unrelated-feedback".to_string();
            let (reloaded, _) = load_sync_session(&client.sync_path);
            assert_eq!(outcome, reloaded.value.last_message);
            assert_eq!(123, reloaded.value.last_sync_at_epoch_millis);
            drop(client);
            fs::remove_dir_all(dir).unwrap();
        }
    }

    #[test]
    fn media_preflight_blocks_app_data_when_any_attachment_is_unresolved() {
        let mut summary =
            gridtimer_native::desktop_note_media_sync::DesktopNoteMediaSyncSummary::default();
        assert!(note_media_preflight_allows_app_data(&summary));

        summary.legacy_missing = 6;
        assert!(note_media_preflight_allows_app_data(&summary));
        summary.deferred_reference_deletions = 2;
        summary.private_media_pending = 3;
        assert!(
            note_media_preflight_allows_app_data(&summary),
            "reference metadata waits for the AppData commit"
        );
        summary.conflicts = 1;
        assert!(!note_media_preflight_allows_app_data(&summary));
        summary.conflicts = 0;
        summary.failures = 1;
        assert!(!note_media_preflight_allows_app_data(&summary));
        summary.failures = 0;
        summary.quota_rejected = true;
        assert!(!note_media_preflight_allows_app_data(&summary));
        summary.quota_rejected = false;
        summary.restore_required = true;
        assert!(!note_media_preflight_allows_app_data(&summary));
    }

